{
  "perspective": "Theoretical Foundations and Asymptotic Analysis",
  "research_gaps": [
    {
      "gap": "Characterization of Breakdown Points under Unmatched and Misspecified Cluster Structures",
      "why_it_matters": "Understanding breakdown point limits when the assumed number of clusters $k$ does not match the true underlying data manifold is crucial for establishing reliable theoretical performance guarantees in unsupervised robust quantization.",
      "what_is_known": "It is established that trimmed k-means breaks down when contamination proportions exceed specific thresholds, and universal breakdown points for robust k-means variants under arbitrary contamination have been bounded (e.g., $2/n$). Furthermore, specific counterexamples demonstrate that breakdown limits depend heavily on the proportion of mass in hypothesized cluster structures relative to the trimming level $\\alpha$.",
      "what_remains_unknown": "A complete, general mathematical characterization of how breakdown points behave dynamically when $k$ is misspecified relative to the true underlying mixture components remains an open theoretical problem.",
      "gap_type": "explicit",
      "confidence": "high",
      "supporting_papers": [
        {
          "paper_id": "P002",
          "sections": [
            "5. Conclusions",
            "Page 16"
          ]
        }
      ],
      "evidence": [
        {
          "paper_id": "P002",
          "section": "5. Conclusions",
          "evidence": "In other words, the breakdown point generally depends, of course, on the procedure, but it also depends heavily on the data, in the sense that the same procedure can be highly stable with reasonable clusterized data when considering the right number of clusters, but it can also be very unstable in other cases. This is in some way natural and clearly related to the traditional key problem in cluster analysis: how to choose the number of clusters to look for?"
        }
      ]
    },
    {
      "gap": "Relaxation of Strict Separation Bounds for Restricted Robustness Guarantees",
      "why_it_matters": "Theoretical guarantees for robust k-means variants often rely on overly restrictive separation assumptions between inlier clusters; relaxing these bounds is necessary to understand behavior under overlapping or closely situated distributions.",
      "what_is_known": "Under well-structured datasets where inlier samples are covered by balls whose centers are separated by specific distance thresholds, robust k-means variants can ignore outliers and achieve consistency and convergence guarantees.",
      "what_remains_unknown": "It remains unproven whether these restricted robustness and noise-resilience theorems can be extended to weaker separation conditions or overlapping cluster distributions without causing estimator failure.",
      "gap_type": "explicit",
      "confidence": "high",
      "supporting_papers": [
        {
          "paper_id": "P005",
          "sections": [
            "3.3 Restricted robustness of robust k-means for well-clustered data",
            "Page 5"
          ]
        }
      ],
      "evidence": [
        {
          "paper_id": "P005",
          "section": "3.3 Restricted robustness of robust k-means for well-clustered data",
          "evidence": "Using this corollary we are able to design proximal maps for which Theorems 3, 4, and 5 in [2] apply; otherwise, it is not clear how the analysis of [2] is valid for (RKM)."
        }
      ]
    },
    {
      "gap": "Asymptotic Complexity Bounds and Parameter-Free FPT Trade-offs for Outlier-Constrained Clustering",
      "why_it_matters": "Eliminating unnecessary exponential dependencies on the number of outliers $m$ in fixed-parameter tractable (FPT) approximation algorithms is essential for reconciling computational tractability with optimal clustering guarantees in metric spaces.",
      "what_is_known": "General FPT approximation-preserving reduction frameworks can achieve constant-factor approximations for k-MeansOut and k-MedianOut, but their running times inherently scale with an exponential dependence on the number of outliers $m$ through factors like $((k + m)/\\epsilon)^{O(m)}.",
      "what_remains_unknown": "It is fundamentally unknown whether an FPT dependence on the number of outliers $m$ is strictly necessary, or if algorithms running in time FPT in $k$ and $\\epsilon$ alone can achieve matching approximation guarantees.",
      "gap_type": "explicit",
      "confidence": "high",
      "supporting_papers": [
        {
          "paper_id": "P013",
          "sections": [
            "5. Concluding Remarks",
            "Page 16"
          ]
        }
      ],
      "evidence": [
        {
          "paper_id": "P013",
          "section": "5. Concluding Remarks",
          "evidence": "More fundamentally, perhaps, is the question whether we need an FPT dependence on the number of outliers, m; or whether it is possible to obtain approximation guarantees for k-MedianOut matching that for k-Median, with a running time that is FPT in k and \\epsilon alone."
        }
      ]
    }
  ]
}

{
  "perspective": "Algorithmic Modifications and Optimization Strategies",
  "research_gaps": [
    {
      "gap": "Optimization and convergence guarantees for trimmed k-means and related relaxed variants when dealing with non-spherical, anisotropic, or overlapping cluster distributions.",
      "why_it_matters": "Real-world data rarely conform to strict spherical or Gaussian assumptions. Understanding how centroid updates and penalties perform under complex geometries is crucial for robust unsupervised learning.",
      "what_is_known": "Classical trimmed k-means and robust k-means variants (such as Moreau envelope relaxations) rely heavily on spherical assumptions or optimal zones represented as unions of balls. Standard convergence analyses often assume continuous distributions and spherical cluster structures.",
      "what_remains_unknown": "Rigorous convergence guarantees and exact error bounds for modified centroid update rules (like K-means-sharp or RTKM) under heavy cluster overlap, non-spherical shapes, or arbitrary covariance matrices without resorting to spherical restrictions.",
      "gap_type": "explicit",
      "confidence": "high",
      "supporting_papers": [
        {
          "paper_id": "P002",
          "sections": ["5. Conclusions"]
        },
        {
          "paper_id": "P003",
          "sections": ["1. INTRODUCTION", "4. MIXTURES OF ELLIPTICAL DISTRIBUTIONS"]
        },
        {
          "paper_id": "P005",
          "sections": ["3.3 Restricted robustness of robust k-means for well-clustered data"]
        }
      ],
      "evidence": [
        {
          "paper_id": "P002",
          "section": "5. Conclusions",
          "evidence": "Relatively nearby clusters could be badly detected if they are nonspherical or if their shapes are too different, because every cluster obtained is spherical and all share the same radius."
        },
        {
          "paper_id": "P003",
          "section": "1. INTRODUCTION",
          "evidence": "A clear weakness of the proposed approach is that it is specially aimed to mixtures of spherical distributions. This is a shared problem with k-means and other techniques based on this clustering method."
        },
        {
          "paper_id": "P005",
          "section": "3.3 Restricted robustness of robust k-means for well-clustered data",
          "evidence": "In this section, we place two restrictions: i) we consider datasets where inlier samples can be covered by unions of balls with centers that are 'far apart' each other... otherwise, it is not clear how the analysis of [2] is valid for (RKM)."
        }
      ]
    },
    {
      "gap": "Principled, automated parameter estimation for contamination rates and trimming thresholds in outlier-robust k-means formulations.",
      "why_it_matters": "Most robust k-means variants (such as trimmed k-means, RTKM, and k-means-sharp) require user-defined parameters like trimming proportions, expected outlier percentages, or distance thresholds (such as standard deviation multipliers q). Poor selection of these hyperparameters can severely degrade clustering accuracy or lead to high false-positive/false-negative outlier rates.",
      "what_is_known": "Sensitivity analyses (e.g., varying q in k-means#) demonstrate that performance metrics like precision and recall trade off significantly based on threshold coefficients, and empirical guidelines or grid searches are commonly used.",
      "what_remains_unknown": "A principled, automated, data-driven framework to jointly estimate parameters such as trimming proportions, penalty multipliers, and cluster numbers concurrently during the optimization process without heuristic tuning.",
      "gap_type": "explicit",
      "confidence": "high",
      "supporting_papers": [
        {
          "paper_id": "P007",
          "sections": ["Section I"]
        },
        {
          "paper_id": "P009",
          "sections": ["6. Conclusions and future work"]
        }
      ],
      "evidence": [
        {
          "paper_id": "P007",
          "section": "Section I",
          "evidence": "Specifically, what is the optimal value of q when emphasis is on any one of these performance measures? To answer these questions, we study the algorithms performance on 10 datasets."
        },
        {
          "paper_id": "P009",
          "section": "6. Conclusions and future work",
          "evidence": "At the moment, there is no principled approach to estimating the other two parameters alpha and s. We leave the investigation of such an approach for future work..."
        }
      ]
    }
  ]
}

